head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > M > getLongdesc]<br/>Image 컴포넌트에 설정된 longdesc 속성값을 반환합니다.",
    "validation" : [
        "longdesc 속성값을 반환합니다.",
        "longdesc 속성값이 없는 경우 ''(Empty String)을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (longdesc : 별도 페이지 URL)
    con_longdesc.setValue("/sample/image/image_longdesc.html");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cLongdesc = con_longdesc.getValue();

    let lblLongdesc = (cLongdesc === '') ? '미설정' : cLongdesc;

    $c.gcm.createLabel('label="[현재] longdesc = ' + lblLongdesc + '\n[절차] con 값 변경 -> Target 재생성 -> getLongdesc 버튼 클릭\n[확인] 선언한 설정값과 마크업 longdesc 속성값, getLongdesc() 반환값 3자를 나란히 비교합니다"', '', 'label1');

    // 조건 설정 (빈값이면 longdesc 를 선언하지 않는다)
    let properties = {
        longdesc : cLongdesc,
    };

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicImage(cList, '');
}



// getLongdesc 호출 및 validation 항목별 판정 출력
scwin.btn_getLongdesc_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = target1.render;

    // 선언 시 설정한 값 / 마크업에 남은 속성값 / 메소드 반환값
    let setVal  = con_longdesc.getValue();
    let attrVal = img.getAttribute("longdesc");
    let getVal  = target1.getLongdesc();

    let strSet  = (setVal === '') ? "없음 (longdesc 미선언)" : "'" + setVal + "'";
    let strAttr = (attrVal === null) ? "없음 (longdesc 속성 미출력)" : "'" + attrVal + "'";

    bottom.setReturnValue("[1] getLongdesc() 반환값 : '" + getVal + "' (" + typeof getVal + ") / 선언한 설정값 : " + strSet + " / 마크업 longdesc 속성값 : " + strAttr);
    bottom.setReturnValue("[2] longdesc 속성값 없음 여부 : " + (attrVal === null) + " -> getLongdesc() 반환값 : '" + getVal + "' , Empty String 여부 : " + (getVal === ""));
};
